/**
 * ArvoDrawer -- viewport-anchored slide-in overlay panel.
 *
 * Always portaled (default `document.body`, configurable container) and
 * always overlay -- there is no layout/pinned mode (use `ArvoSidePanel`
 * when pinning into the layout is meaningful). Composes the same
 * content shell as `ArvoSidePanel` (header, sticky pre-body region,
 * scrollable body, optional items+filter pipeline, footer) via the
 * shared `panel-shell` pattern, and adds Drawer-only positional
 * concerns: portal mounting, optional backdrop / mask, scroll lock,
 * focus trap, slide-in animation, and Escape / mask-click dismissal.
 *
 * See `descriptors/drawer.json` and `descriptors/drawer-prompt.md`.
 */

import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from 'react';
import type {
  CSSProperties,
  ReactElement,
  ReactNode,
  Ref,
  RefObject,
} from 'react';
import { createPortal } from 'react-dom';

import {
  enter,
  exit,
  lockPageScroll,
  type ListItemBase,
} from '@arvo/core';
import {
  PanelShell,
  type PanelShellHandle,
} from '../PanelShell/PanelShell';
import { useControllableState } from '../../hooks/useControllableState';
import { useFocusTrap } from '../../hooks/useFocusTrap';
import type {
  ArvoPanelHeaderAction,
  ArvoPanelStickyHeaderConfig,
  ArvoPanelBannerConfig,
  ArvoPanelInfoConfig,
  ArvoPanelAction,
} from '@arvo/utils';

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export type ArvoDrawerSide = 'left' | 'right' | 'top' | 'bottom';
export type ArvoDrawerCloseReason =
  | 'escape'
  | 'mask-click'
  | 'close-button'
  | 'programmatic';

export type ArvoDrawerMaskVariant = 'light' | 'dark';

export interface ArvoDrawerMaskConfig {
  variant?: ArvoDrawerMaskVariant;
  opacity?: number;
  blur?: number;
  closeOnClick?: boolean;
}

export interface ArvoDrawerHandle<T extends ListItemBase = ListItemBase> {
  open(): void;
  close(reason?: ArvoDrawerCloseReason): void;
  toggle(): void;
  isOpen(): boolean;
  setItems(items: T[]): void;
  setStickyHeader(config: ArvoPanelStickyHeaderConfig | false): void;
  setHeaderActions(actions: ArvoPanelHeaderAction[]): void;
  setActions(actions: ArvoPanelAction[] | false): void;
  updateAction(
    id: string,
    patch: Partial<ArvoPanelHeaderAction | ArvoPanelAction>,
  ): void;
  search(query?: string): string | void;
  selectedTab(id?: string): string | null | void;
  setTitle(title: string | null): void;
  loading(state?: boolean): boolean | void;
  disabled(state?: boolean): boolean | void;
  focus(target?: 'first' | 'title' | 'search' | 'list'): void;
}

export interface ArvoDrawerProps<T extends ListItemBase = ListItemBase>
  extends Omit<
    React.HTMLAttributes<HTMLDivElement>,
    'onClose' | 'onSelect' | 'title'
  > {
  side?: ArvoDrawerSide;

  isOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  onOpen?: () => boolean | void;
  onClose?: (reason: ArvoDrawerCloseReason) => boolean | void;

  hasMask?: boolean | ArvoDrawerMaskConfig;
  closeOnEscape?: boolean;
  closeOnMaskClick?: boolean;
  lockScroll?: boolean | 'auto';

  container?: HTMLElement | (() => HTMLElement) | null;

  width?: string | number;
  minWidth?: string | number;
  maxWidth?: string | number;
  height?: string | number | null;

  animationDuration?: number;

  ariaLabel?: string;
  ariaLabelledBy?: string;

  isClosable?: boolean;
  isDisabled?: boolean;
  isLoading?: boolean;

  className?: string;
  children?: ReactNode;

  /**
   * Forwarded to the imperative handle. The forwarded `ref` always points to
   * the host `.arvo-drw` element; use `instanceRef` for the imperative API.
   */
  instanceRef?: Ref<ArvoDrawerHandle>;

  // -- Forwarded to PanelShell ----------------------------------------------
  title?: string | null;
  hasHeader?: boolean;
  hasBackButton?: boolean;
  onBack?: () => void;
  headerActions?: ArvoPanelHeaderAction[];
  stickyHeader?: ArvoPanelStickyHeaderConfig | false;

  items?: T[];
  getItemId?: (item: T) => string;
  filterKeys?: Array<keyof T & string>;
  getItemSearchText?: (item: T) => string;
  renderItem?: (item: T) => ReactNode;
  itemsRole?: 'listbox' | 'list' | 'menu';

  actions?: ArvoPanelAction[] | false;
  hasFooter?: boolean;

  searchQuery?: string;
  defaultSearchQuery?: string;
  onSearchChange?: (query: string, matchedCount: number | null) => void;
  onItemActivate?: (id: string, item: T) => void;
  onTabSelect?: (id: string) => void;
}

// ---------------------------------------------------------------------------
// Re-exports of panel-shell types (consumer convenience)
// ---------------------------------------------------------------------------

export type {
  ArvoPanelHeaderAction,
  ArvoPanelStickyHeaderConfig,
  ArvoPanelBannerConfig,
  ArvoPanelInfoConfig,
  ArvoPanelAction,
};

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const DEFAULT_LIGHT_OPACITY = 0.32;
const DEFAULT_DARK_OPACITY = 0.5;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function toCssLength(
  value: string | number | null | undefined,
): string | undefined {
  if (value === null || value === undefined) return undefined;
  return typeof value === 'number' ? `${value}px` : value;
}

interface ResolvedMask {
  hasMask: boolean;
  variant: ArvoDrawerMaskVariant;
  opacity: number;
  blur: number;
  closeOnClick: boolean;
}

function resolveMask(
  hasMask: boolean | ArvoDrawerMaskConfig | undefined,
  closeOnMaskClickProp: boolean,
): ResolvedMask {
  // Default (undefined) and explicit `false` both render no mask. Consumers
  // opt in to a backdrop by passing `hasMask={true}` or a mask config object.
  if (hasMask === undefined || hasMask === false) {
    return {
      hasMask: false,
      variant: 'light',
      opacity: 0,
      blur: 0,
      closeOnClick: false,
    };
  }

  if (hasMask === true) {
    return {
      hasMask: true,
      variant: 'light',
      opacity: DEFAULT_LIGHT_OPACITY,
      blur: 0,
      closeOnClick: closeOnMaskClickProp,
    };
  }

  const variant = hasMask.variant ?? 'light';
  const opacity =
    hasMask.opacity ??
    (variant === 'dark' ? DEFAULT_DARK_OPACITY : DEFAULT_LIGHT_OPACITY);
  return {
    hasMask: true,
    variant,
    opacity,
    blur: hasMask.blur ?? 0,
    closeOnClick: hasMask.closeOnClick ?? closeOnMaskClickProp,
  };
}

function resolveSide(side: ArvoDrawerSide): 'left' | 'right' {
  if (side === 'top' || side === 'bottom') {
    if (typeof process !== 'undefined' && process.env.NODE_ENV !== 'production') {
      console.warn(
        `[ArvoDrawer] side='${side}' not yet implemented; using 'right'.`,
      );
    }
    return 'right';
  }
  return side;
}

function resolveContainer(
  container: HTMLElement | (() => HTMLElement) | null | undefined,
): HTMLElement | null {
  if (typeof document === 'undefined') return null;
  if (container == null) return document.body;
  if (typeof container === 'function') return container();
  return container;
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

function DrawerInner<T extends ListItemBase = ListItemBase>(
  props: ArvoDrawerProps<T>,
  ref: React.ForwardedRef<HTMLDivElement>,
) {
  const {
    side: sideProp = 'right',

    isOpen: isOpenProp,
    defaultOpen = false,
    onOpenChange,
    onOpen,
    onClose,

    hasMask = false,
    closeOnEscape = true,
    closeOnMaskClick = true,
    lockScroll = 'auto',

    container,

    width = 320,
    minWidth = 280,
    maxWidth = '80vw',
    height = null,

    animationDuration,

    ariaLabel,
    ariaLabelledBy,

    isClosable = true,
    isDisabled = false,
    isLoading = false,

    className,
    children,
    instanceRef,

    // PanelShell passthrough
    title = null,
    hasHeader = true,
    hasBackButton = false,
    onBack,
    headerActions,
    stickyHeader = false,
    items,
    getItemId,
    filterKeys,
    getItemSearchText,
    renderItem,
    itemsRole,
    actions = false,
    hasFooter,
    searchQuery,
    defaultSearchQuery,
    onSearchChange,
    onItemActivate,
    onTabSelect,

    ...rest
  } = props;

  // Mark as intentionally accepted but unused by this React layer (PanelShell
  // derives footer visibility from `actions`). Documented for descriptor parity.
  void hasFooter;
  void height;

  // -- Resolved values -----------------------------------------------------
  const side = resolveSide(sideProp);
  const mask = useMemo(
    () => resolveMask(hasMask, closeOnMaskClick),
    [hasMask, closeOnMaskClick],
  );
  const lockScrollResolved =
    lockScroll === 'auto' ? mask.hasMask : lockScroll === true;

  // -- Refs ----------------------------------------------------------------
  const hostRef = useRef<HTMLDivElement>(null);
  const paneRef = useRef<HTMLDivElement>(null);
  const backdropRef = useRef<HTMLDivElement>(null);
  const shellRef = useRef<PanelShellHandle>(null);
  const prevFocusRef = useRef<HTMLElement | null>(null);
  const scrollUnlockRef = useRef<(() => void) | null>(null);

  // Forward host ref to consumer
  useImperativeHandle(ref, () => hostRef.current as HTMLDivElement, []);

  // Focus trap activates only after slide-in completes.
  const [trapActive, setTrapActive] = useState(false);

  // -- Controlled open state -----------------------------------------------
  const [isOpenState, setOpenInternal] = useControllableState<boolean>(
    isOpenProp,
    defaultOpen,
  );

  const setOpen = useCallback(
    (next: boolean) => {
      if (next === isOpenState) return;
      setOpenInternal(next);
      onOpenChange?.(next);
    },
    [isOpenState, onOpenChange, setOpenInternal],
  );

  // -- Container resolution (memoized so portal stays stable) ---------------
  const [resolvedContainer, setResolvedContainer] = useState<HTMLElement | null>(
    () => resolveContainer(container),
  );
  useEffect(() => {
    // Re-resolve when container prop identity changes.
    setResolvedContainer(resolveContainer(container));
  }, [container]);

  // -- Open / close lifecycle ----------------------------------------------
  const handleOpen = useCallback(() => {
    if (isOpenState) return;
    if (onOpen?.() === false) return;
    if (typeof document !== 'undefined') {
      prevFocusRef.current = document.activeElement as HTMLElement | null;
    }
    setOpen(true);
  }, [isOpenState, onOpen, setOpen]);

  const handleClose = useCallback(
    (reason: ArvoDrawerCloseReason = 'programmatic') => {
      if (!isOpenState) return;
      // onClose receives the reason and may cancel by returning false.
      const cancelled =
        onClose !== undefined && onClose(reason) === false;
      if (cancelled) return;

      // Capture the close reason for the post-slide-out detail dispatch.
      pendingCloseReasonRef.current = reason;
      setOpen(false);
    },
    [isOpenState, onClose, setOpen],
  );

  const pendingCloseReasonRef = useRef<ArvoDrawerCloseReason>('programmatic');

  const handleToggle = useCallback(() => {
    if (isOpenState) handleClose('programmatic');
    else handleOpen();
  }, [isOpenState, handleOpen, handleClose]);

  // -- Animation lifecycle -------------------------------------------------
  const wasOpenRef = useRef<boolean>(isOpenState);
  useEffect(() => {
    const prevOpen = wasOpenRef.current;
    wasOpenRef.current = isOpenState;
    if (isOpenState === prevOpen) return;

    const host = hostRef.current;
    const pane = paneRef.current;

    if (isOpenState) {
      // Apply the configurable animation duration as an inline CSS variable.
      if (animationDuration && pane) {
        pane.style.setProperty(
          '--arvo-drw-slide-duration',
          `${animationDuration}ms`,
        );
      }
      if (host) {
        void enter({ element: host, type: 'fade' }).then(() => {
          // Activate focus trap only AFTER slide-in completes.
          setTrapActive(true);
          pane?.dispatchEvent(
            new CustomEvent('drw:open', { bubbles: true }),
          );
        });
      } else {
        setTrapActive(true);
      }
    } else {
      // Deactivate trap synchronously BEFORE slide-out begins.
      setTrapActive(false);
      const reason = pendingCloseReasonRef.current;
      pendingCloseReasonRef.current = 'programmatic';

      const finishClose = () => {
        pane?.dispatchEvent(
          new CustomEvent('drw:close', {
            bubbles: true,
            detail: { reason },
          }),
        );
        const prev = prevFocusRef.current;
        prevFocusRef.current = null;
        if (prev && typeof prev.focus === 'function') {
          try {
            prev.focus({ preventScroll: true });
          } catch {
            /* element may have been removed; swallow */
          }
        }
      };

      if (host) {
        void exit({ element: host, type: 'fade' }).then(finishClose);
      } else {
        finishClose();
      }
    }
  }, [isOpenState, animationDuration]);

  // -- Scroll lock lifecycle -----------------------------------------------
  useEffect(() => {
    if (isOpenState && lockScrollResolved) {
      scrollUnlockRef.current = lockPageScroll();
    }
    return () => {
      if (scrollUnlockRef.current) {
        scrollUnlockRef.current();
        scrollUnlockRef.current = null;
      }
    };
  }, [isOpenState, lockScrollResolved]);

  // -- Focus trap (always active when open + slide-in complete) ------------
  useFocusTrap(paneRef, {
    active: isOpenState && trapActive && !isDisabled,
    initialFocus: 'first',
    escapeDeactivates: false,
    returnFocusOnDeactivate: false,
    allowOutsideClick: true,
  });

  // -- Escape handling -----------------------------------------------------
  useEffect(() => {
    if (!isOpenState || !closeOnEscape) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.stopPropagation();
        handleClose('escape');
      }
    };
    document.addEventListener('keydown', onKeyDown, true);
    return () => document.removeEventListener('keydown', onKeyDown, true);
  }, [isOpenState, closeOnEscape, handleClose]);

  // -- Mask click handler --------------------------------------------------
  const handleMaskMouseDown = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      // Only fire on direct backdrop clicks (not bubbled from inside the pane).
      if (e.target !== e.currentTarget) return;
      const pane = paneRef.current;
      pane?.dispatchEvent(
        new CustomEvent('drw:mask-click', { bubbles: true }),
      );
      if (mask.closeOnClick) {
        handleClose('mask-click');
      }
    },
    [mask.closeOnClick, handleClose],
  );

  // -- Imperative handle ---------------------------------------------------
  useImperativeHandle(
    instanceRef,
    () => ({
      open: () => handleOpen(),
      close: (reason?: ArvoDrawerCloseReason) =>
        handleClose(reason ?? 'programmatic'),
      toggle: () => handleToggle(),
      isOpen: () => isOpenState,
      setItems: (next) => shellRef.current?.setItems(next as ListItemBase[]),
      setStickyHeader: (config) => shellRef.current?.setStickyHeader(config),
      setHeaderActions: (next) => shellRef.current?.setHeaderActions(next),
      setActions: (next) => shellRef.current?.setActions(next),
      updateAction: (id, patch) => shellRef.current?.updateAction(id, patch),
      search(query?: string): string | void {
        if (query === undefined) return shellRef.current?.search() ?? '';
        shellRef.current?.search(query);
      },
      selectedTab(id?: string): string | null | void {
        if (id === undefined) return shellRef.current?.selectedTab() ?? null;
        shellRef.current?.selectedTab(id);
      },
      setTitle: (next) => shellRef.current?.setTitle(next),
      loading(state?: boolean): boolean | void {
        if (state === undefined) return isLoading;
        shellRef.current?.loading(state);
      },
      disabled(state?: boolean): boolean | void {
        if (state === undefined) return isDisabled;
        shellRef.current?.disabled(state);
      },
      focus: (target) => shellRef.current?.focus(target),
    }),
    [
      handleOpen,
      handleClose,
      handleToggle,
      isOpenState,
      isLoading,
      isDisabled,
    ],
  );

  // -- Class composition ---------------------------------------------------
  const hostClasses = [
    'arvo-drw',
    `arvo-drw--side-${side}`,
    mask.hasMask && 'arvo-drw--with-mask',
    mask.hasMask && `arvo-drw--mask-${mask.variant}`,
    isOpenState && 'open',
    isLoading && 'loading',
    isDisabled && 'is-disabled',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  // -- Inline CSS variables ------------------------------------------------
  const styleVars = useMemo<CSSProperties>(() => {
    const out: Record<string, string> = {};
    const w = toCssLength(width);
    const minW = toCssLength(minWidth);
    const maxW = toCssLength(maxWidth);
    if (w) out['--arvo-drw-width'] = w;
    if (minW) out['--arvo-drw-min-width'] = minW;
    if (maxW) out['--arvo-drw-max-width'] = maxW;
    if (animationDuration) {
      out['--arvo-drw-slide-duration'] = `${animationDuration}ms`;
    }
    return out as CSSProperties;
  }, [width, minWidth, maxWidth, animationDuration]);

  const backdropStyle = useMemo<CSSProperties>(() => {
    if (!mask.hasMask) return {};
    const out: CSSProperties = {
      backgroundColor: `rgba(0, 0, 0, ${mask.opacity})`,
    };
    if (mask.blur > 0) {
      out.backdropFilter = `blur(${mask.blur}px)`;
      // Vendor prefix for broader browser support
      (out as Record<string, string>).WebkitBackdropFilter = `blur(${mask.blur}px)`;
    }
    return out;
  }, [mask]);

  // -- ARIA wiring ---------------------------------------------------------
  const ariaModalAttr = mask.hasMask ? 'true' : 'false';
  const ariaHiddenAttr = !isOpenState ? true : undefined;
  const computedAriaLabel =
    !title && ariaLabel ? ariaLabel : !title ? undefined : undefined;
  // aria-labelledby auto-set to the panel-shell __title id when title is
  // provided and consumer has not overridden via ariaLabelledBy.
  // PanelShell internally generates the id and writes aria-labelledby on
  // its host (which is __pane) via its own composition. We honor explicit
  // ariaLabelledBy if provided.
  const computedAriaLabelledBy = ariaLabelledBy;

  // -- Render --------------------------------------------------------------
  if (!resolvedContainer) {
    // SSR guard / not yet mounted -- nothing to portal.
    return null;
  }

  // Suppress portal rendering entirely when closed AND the slide-out has
  // completed (host element is removed from the DOM). For now we keep the
  // host mounted so transitions can fire; visibility is controlled via the
  // SCSS `transform` offset on the pane in non-`.open` states.

  const portalContents = (
    <>
      {mask.hasMask && (
        <div
          ref={backdropRef}
          className="arvo-drw__backdrop arvo-backdrop arvo-backdrop--animated"
          style={backdropStyle}
          onMouseDown={handleMaskMouseDown}
          aria-hidden="true"
        />
      )}
      <div
        ref={hostRef}
        className={hostClasses}
        style={styleVars}
        {...rest}
      >
        <div
          ref={paneRef}
          className="arvo-drw__pane"
          role="dialog"
          aria-modal={ariaModalAttr}
          aria-hidden={ariaHiddenAttr}
          aria-busy={isLoading || undefined}
          aria-disabled={isDisabled || undefined}
          aria-label={computedAriaLabel}
          aria-labelledby={computedAriaLabelledBy}
        >
          <PanelShell<T>
            ref={shellRef as RefObject<PanelShellHandle>}
            parentBlock="arvo-drw"
            title={title}
            hasHeader={hasHeader}
            hasBackButton={hasBackButton}
            onBack={onBack}
            headerActions={headerActions}
            stickyHeader={stickyHeader}
            items={items}
            getItemId={getItemId}
            filterKeys={filterKeys}
            getItemSearchText={getItemSearchText}
            renderItem={renderItem}
            itemsRole={itemsRole}
            actions={actions}
            isClosable={isClosable}
            onClose={() => handleClose('close-button')}
            isLoading={isLoading}
            isDisabled={isDisabled}
            isClosableCount={isClosable ? 1 : 0}
            searchQuery={searchQuery}
            defaultSearchQuery={defaultSearchQuery}
            onSearchChange={onSearchChange}
            onItemActivate={onItemActivate}
            onTabSelect={onTabSelect}
          >
            {children}
          </PanelShell>
        </div>
      </div>
    </>
  );

  return createPortal(portalContents, resolvedContainer);
}

// Cast the forwardRef'd inner function to a generic component signature so
// consumers retain the `<T>` type parameter. Mirrors PanelShell.tsx /
// SidePanel.tsx pattern.
export const ArvoDrawer = forwardRef(DrawerInner) as <
  T extends ListItemBase = ListItemBase,
>(
  props: ArvoDrawerProps<T> & { ref?: Ref<HTMLDivElement> },
) => ReactElement | null;

(ArvoDrawer as unknown as { displayName: string }).displayName = 'ArvoDrawer';

export default ArvoDrawer;
